  "kidsPrayer.quiz.q3.opt3": { fr: "Subhana Rabbiyal A'la", en: "Subhana Rabbiyal A'la", nl: "Subhana Rabbiyal A'la", ar: "سبحان ربي الأعلى", tr: "Sübhane Rabbiyel A'la", ur: "سبحان ربی الاعلیٰ" },
  "kidsPrayer.quiz.q4": { fr: "Comment termine-t-on la prière ?", en: "How do you end the prayer?", nl: "Hoe eindig je het gebed?", ar: "كيف تُنهي الصلاة؟", tr: "Namaz nasıl bitirilir?", ur: "نماز کیسے ختم ہوتی ہے؟" },
  "kidsPrayer.quiz.q4.opt1": { fr: "Assalamu Alaykum wa Rahmatullah", en: "Assalamu Alaykum wa Rahmatullah", nl: "Assalamu Alaykum wa Rahmatullah", ar: "السلام عليكم ورحمة الله", tr: "Esselamu Aleykum ve Rahmetullah", ur: "السلام علیکم ورحمۃ اللہ" },
