  "kidsDuas.quizTitle": { fr: "Quiz Dou'a", en: "Du'a Quiz", nl: "Doe'a Quiz", ar: "اختبار الأدعية", tr: "Dua Testi", ur: "دعا کوئز" },
  "kidsDuas.quizDesc": { fr: "Teste tes connaissances sur les dou'a !", en: "Test your knowledge of du'as!", nl: "Test je kennis van doe'as!", ar: "اختبر معرفتك بالأدعية!", tr: "Dua bilgini test et!", ur: "اپنی دعاؤں کا علم جانچیں!" },
  "kidsDuas.quizQuestion": { fr: "Quelle dou'a correspond à cette situation ?", en: "Which du'a matches this situation?", nl: "Welke doe'a past bij deze situatie?", ar: "أي دعاء يناسب هذا الموقف؟", tr: "Bu duruma hangi dua uyar?", ur: "اس صورت حال میں کون سی دعا پڑھی جائے؟" },
  "kidsDuas.quizExcellent": { fr: "Excellent ! Tu connais très bien tes dou'a !", en: "Excellent! You know your du'as very well!", nl: "Uitstekend! Je kent je doe'as heel goed!", ar: "ممتاز! أنت تعرف أدعيتك جيدًا!", tr: "Mükemmel! Dualarını çok iyi biliyorsun!", ur: "بہترین! آپ اپنی دعائیں بہت اچھی جانتے ہیں!" },
  "kidsDuas.quizGood": { fr: "Bien joué ! Continue d'apprendre !", en: "Well played! Keep learning!", nl: "Goed gespeeld! Blijf leren!", ar: "أحسنت! واصل التعلم!", tr: "İyi oynadın! Öğrenmeye devam et!", ur: "شاباش! سیکھتے رہیں!" },
  "kidsDuas.quizRetry": { fr: "Révise un peu et réessaie !", en: "Review a bit and try again!", nl: "Herzie een beetje en probeer opnieuw!", ar: "راجع قليلاً وحاول مرة أخرى!", tr: "Biraz tekrar et ve tekrar dene!", ur: "تھوڑا دہرائیں اور دوبارہ کوشش کریں!" },
