  "reset.submit": { fr: "Réinitialiser le mot de passe", en: "Reset password", nl: "Wachtwoord resetten", ar: "إعادة تعيين كلمة المرور", tr: "Şifreyi sıfırla", ur: "پاسورڈ ری سیٹ کریں" },
  "reset.resend": { fr: "Renvoyer le code", en: "Resend code", nl: "Code opnieuw verzenden", ar: "إعادة إرسال الرمز", tr: "Kodu tekrar gönder", ur: "کوڈ دوبارہ بھیجیں" },
