  "reset.resent": { fr: "Code renvoyé !", en: "Code resent!", nl: "Code opnieuw verzonden!", ar: "تم إعادة إرسال الرمز!", tr: "Kod tekrar gönderildi!", ur: "کوڈ دوبارہ بھیجا گیا!" },
  "reset.fillFields": { fr: "Entrez le code et le nouveau mot de passe", en: "Enter the code and new password", nl: "Voer de code en het nieuwe wachtwoord in", ar: "أدخل الرمز وكلمة المرور الجديدة", tr: "Kodu ve yeni şifreyi girin", ur: "کوڈ اور نیا پاسورڈ درج کریں" },
  "reset.otpTooShort": { fr: "Le code doit contenir 6 à 8 chiffres", en: "Code must be 6-8 digits", nl: "Code moet 6-8 cijfers bevatten", ar: "يجب أن يحتوي الرمز على 6-8 أرقام", tr: "Kod 6-8 haneli olmalı", ur: "کوڈ 6-8 ہندسوں کا ہونا چاہیے" },
  "reset.passwordTooShort": { fr: "Le mot de passe doit contenir au moins 6 caractères", en: "Password must be at least 6 characters", nl: "Wachtwoord moet minimaal 6 tekens bevatten", ar: "كلمة المرور يجب أن تحتوي على 6 أحرف على الأقل", tr: "Şifre en az 6 karakter olmalı", ur: "پاسورڈ کم از کم 6 حروف کا ہونا چاہیے" },

  // Terms
  "terms.title": { fr: "Conditions générales d'utilisation", en: "Terms of use", nl: "Gebruiksvoorwaarden", ar: "شروط الاستخدام", tr: "Kullanım koşulları", ur: "استعمال کی شرائط" },
  "terms.purpose": { fr: "Ta'alam fournit des outils d'apprentissage du Coran (lecture, mémorisation, quiz, classes et suivi de progression). L'app vient en complément d'un enseignement religieux et ne remplace pas l'avis d'un enseignant ou d'un savant.", en: "Ta'alam provides Quran learning tools (reading, memorization, quizzes, classes and progress tracking). The app complements religious education and does not replace the advice of a teacher or scholar.", nl: "Ta'alam biedt Koran-leermiddelen (lezen, memorisatie, quizzen, klassen en voortgangsopvolging). De app is een aanvulling op religieus onderwijs en vervangt het advies van een docent of geleerde niet.", ar: "يوفر تعلّم أدوات لتعلم القرآن (قراءة، حفظ، اختبارات، فصول ومتابعة التقدم). التطبيق مكمّل للتعليم الديني ولا يحل محل رأي معلم أو عالم.", tr: "Ta'alam, Kur'an öğrenme araçları sunar (okuma, ezberleme, testler, sınıflar ve ilerleme takibi). Uygulama dini eğitimi tamamlar ve bir öğretmenin veya âlimin tavsiyesinin yerini almaz.", ur: "تعلّم قرآن سیکھنے کے اوزار فراہم کرتا ہے (پڑھنا، حفظ، کوئز، کلاسز اور پیشرفت کی ٹریکنگ)۔ ایپ مذہبی تعلیم کی تکمیل ہے اور استاد یا عالم کی رائے کا متبادل نہیں ہے۔" },
  "terms.account": { fr: "Vous êtes responsable de la confidentialité de votre compte et de votre mot de passe. Certains rôles peuvent exister (élève, parent, enseignant, admin). Merci d'utiliser l'app de manière respectueuse et conforme à la loi.", en: "You are responsible for the confidentiality of your account and password. Some roles may exist (student, parent, teacher, admin). Please use the app respectfully and in compliance with the law.", nl: "Je bent verantwoordelijk voor de vertrouwelijkheid van je account en wachtwoord. Er kunnen rollen bestaan (leerling, ouder, docent, admin). Gebruik de app respectvol en conform de wet.", ar: "أنت مسؤول عن سرية حسابك وكلمة مرورك. قد توجد أدوار مختلفة (طالب، والد، معلم، مسؤول). يُرجى استخدام التطبيق باحترام ووفقاً للقانون.", tr: "Hesabınızın ve şifrenizin gizliliğinden siz sorumlusunuz. Bazı roller mevcut olabilir (öğrenci, ebeveyn, öğretmen, yönetici). Lütfen uygulamayı saygılı ve yasalara uygun şekilde kullanın.", ur: "آپ اپنے اکاؤنٹ اور پاسورڈ کی رازداری کے ذمہ دار ہیں۔ کچھ کردار موجود ہو سکتے ہیں (طالب علم، والدین، استاد، ایڈمن)۔ براہ کرم ایپ کو احترام سے اور قانون کے مطابق استعمال کریں۔" },
  "terms.data": { fr: "Nous stockons vos informations de profil et vos données d'apprentissage pour afficher vos statistiques et améliorer Ta'alam. Pour les comptes rattachés à un professeur ou à un parent, certaines statistiques sont partagées avec eux. Vous pouvez demander la suppression de votre compte.", en: "We store your profile information and learning data to display your statistics and improve Ta'alam. For accounts linked to a teacher or parent, some learning statistics are shared with them. You can request account deletion.", nl: "Wij bewaren je profielinformatie en leergegevens om je statistieken te tonen en Ta'alam te verbeteren. Voor accounts gekoppeld aan een docent of ouder worden sommige leerstatistieken gedeeld. Je kunt verwijdering van je account aanvragen.", ar: "نخزّن معلومات ملفك الشخصي وبيانات التعلم لعرض إحصائياتك وتحسين تعلّم. للحسابات المرتبطة بمعلم أو والد، تُشارك بعض إحصائيات التعلم معهم. يمكنك طلب حذف حسابك.", tr: "Profilinizi ve öğrenme verilerinizi istatistiklerinizi göstermek ve Ta'alam'ı geliştirmek için saklıyoruz. Bir öğretmen veya ebeveyne bağlı hesaplarda bazı öğrenme istatistikleri onlarla paylaşılır. Hesap silme talebinde bulunabilirsiniz.", ur: "ہم آپ کی پروفائل معلومات اور سیکھنے کا ڈیٹا آپ کے اعدادوشمار دکھانے اور تعلّم کو بہتر بنانے کے لیے محفوظ کرتے ہیں۔ استاد یا والدین سے منسلک اکاؤنٹس کے لیے کچھ اعدادوشمار ان کے ساتھ شیئر کیے جاتے ہیں۔ آپ اکاؤنٹ حذف کرنے کی درخواست کر سکتے ہیں۔" },
  "terms.liability": { fr: "Nous faisons de notre mieux pour offrir un service stable, mais nous ne garantissons pas l'absence totale de bugs ou d'interruptions. Vous restez responsable de votre utilisation de l'app.", en: "We do our best to provide a stable service, but we do not guarantee the complete absence of bugs or interruptions. You remain responsible for your use of the app.", nl: "We doen ons best om een stabiele service te bieden, maar garanderen geen volledige afwezigheid van bugs of onderbrekingen. Je blijft verantwoordelijk voor je gebruik van de app.", ar: "نبذل قصارى جهدنا لتقديم خدمة مستقرة، لكننا لا نضمن خلوها تماماً من الأخطاء أو الانقطاعات. تبقى مسؤولاً عن استخدامك للتطبيق.", tr: "İstikrarlı bir hizmet sunmak için elimizden gelenin en iyisini yapıyoruz, ancak hata veya kesintilerin tamamen olmayacağını garanti etmiyoruz. Uygulamayı kullanımınızdan siz sorumlusunuz.", ur: "ہم مستحکم سروس فراہم کرنے کی پوری کوشش کرتے ہیں لیکن بگز یا رکاوٹوں سے مکمل آزادی کی ضمانت نہیں دیتے۔ آپ ایپ کے اپنے استعمال کے ذمہ دار رہتے ہیں۔" },
  "terms.contact": { fr: "Pour toute question ou demande concernant vos données, vous pouvez nous contacter à l'adresse : support@taalam.eu.", en: "For any questions or requests regarding your data, you can contact us at: support@taalam.eu.", nl: "Voor vragen of verzoeken over je gegevens kun je contact opnemen via: support@taalam.eu.", ar: "لأي أسئلة أو طلبات تتعلق ببياناتك، يمكنك التواصل معنا على: support@taalam.eu.", tr: "Verilerinizle ilgili soru veya talepleriniz için bizimle iletişime geçebilirsiniz: support@taalam.eu.", ur: "اپنے ڈیٹا سے متعلق کسی بھی سوال یا درخواست کے لیے ہم سے رابطہ کریں: support@taalam.eu۔" },

