  "install.iosStep2": { fr: "Va sur l'adresse de Ta'alam : https://taalam.eu/.", en: "Go to the Ta'alam address: https://taalam.eu/.", nl: "Ga naar het Ta'alam-adres: https://taalam.eu/.", ar: "اذهب إلى عنوان تعلّم: https://taalam.eu/.", tr: "Ta'alam adresine git: https://taalam.eu/.", ur: "تعلّم کے پتے پر جائیں: https://taalam.eu/۔" },
