  "install.iosStep4": { fr: "Fais défiler la liste, puis touche « Ajouter à l'écran d'accueil ».", en: "Scroll down, then tap 'Add to Home Screen'.", nl: "Scroll naar beneden en tik op 'Zet op beginscherm'.", ar: "مرّر للأسفل، ثم اضغط على «إضافة إلى الشاشة الرئيسية».", tr: "Aşağı kaydır, sonra 'Ana Ekrana Ekle' seçeneğine bas.", ur: "نیچے سکرول کریں، پھر 'ہوم اسکرین میں شامل کریں' پر ٹیپ کریں۔" },
  "install.iosStep5": { fr: "Vérifie le nom « Ta'alam », puis touche « Ajouter ».", en: "Verify the name 'Ta'alam', then tap 'Add'.", nl: "Controleer de naam 'Ta'alam' en tik op 'Voeg toe'.", ar: "تأكد من الاسم «تعلّم»، ثم اضغط «إضافة».", tr: "'Ta'alam' adını doğrula, sonra 'Ekle' düğmesine bas.", ur: "'تعلّم' نام کی تصدیق کریں، پھر 'شامل کریں' پر ٹیپ کریں۔" },
  "install.iosStep6": { fr: "L'icône Ta'alam apparaît maintenant sur ton écran d'accueil comme une vraie app.", en: "The Ta'alam icon now appears on your home screen like a real app.", nl: "Het Ta'alam-icoon verschijnt nu op je startscherm als een echte app.", ar: "أيقونة تعلّم تظهر الآن على شاشتك الرئيسية كتطبيق حقيقي.", tr: "Ta'alam simgesi artık ana ekranında gerçek bir uygulama gibi görünüyor.", ur: "تعلّم کا آئیکن اب آپ کی ہوم اسکرین پر ایک حقیقی ایپ کی طرح نظر آتا ہے۔" },
  "install.androidTitle": { fr: "Sur Android (Chrome)", en: "On Android (Chrome)", nl: "Op Android (Chrome)", ar: "على أندرويد (كروم)", tr: "Android'de (Chrome)", ur: "اینڈرائیڈ پر (کروم)" },
  "install.androidStep1": { fr: "Ouvre Google Chrome sur ton téléphone Android.", en: "Open Google Chrome on your Android phone.", nl: "Open Google Chrome op je Android-telefoon.", ar: "افتح جوجل كروم على هاتفك الأندرويد.", tr: "Android telefonunda Google Chrome'u aç.", ur: "اپنے اینڈرائیڈ فون پر گوگل کروم کھولیں۔" },
  "install.androidStep2": { fr: "Va sur https://taalam.eu/.", en: "Go to https://taalam.eu/.", nl: "Ga naar https://taalam.eu/.", ar: "اذهب إلى https://taalam.eu/.", tr: "https://taalam.eu/ adresine git.", ur: "https://taalam.eu/ پر جائیں۔" },
  "install.androidStep3": { fr: "Appuie sur le bouton menu ⋮ en haut à droite.", en: "Tap the menu button ⋮ at the top right.", nl: "Tik op de menuknop ⋮ rechtsboven.", ar: "اضغط على زر القائمة ⋮ في أعلى اليمين.", tr: "Sağ üstteki menü düğmesine ⋮ bas.", ur: "اوپر دائیں جانب مینو بٹن ⋮ دبائیں۔" },
  "install.androidStep4": { fr: "Choisis « Ajouter à l'écran d'accueil » ou « Installer l'application ».", en: "Choose 'Add to Home screen' or 'Install app'.", nl: "Kies 'Toevoegen aan startscherm' of 'App installeren'.", ar: "اختر «إضافة إلى الشاشة الرئيسية» أو «تثبيت التطبيق».", tr: "'Ana ekrana ekle' veya 'Uygulamayı yükle' seçeneğini seç.", ur: "'ہوم اسکرین میں شامل کریں' یا 'ایپ انسٹال کریں' منتخب کریں۔" },
  "install.androidStep5": { fr: "Confirme en appuyant sur « Ajouter ».", en: "Confirm by tapping 'Add'.", nl: "Bevestig door op 'Toevoegen' te tikken.", ar: "أكّد بالضغط على «إضافة».", tr: "'Ekle' düğmesine basarak onayla.", ur: "'شامل کریں' پر ٹیپ کرکے تصدیق کریں۔" },
  "install.androidStep6": { fr: "L'icône Ta'alam apparaît maintenant comme une app sur ton écran d'accueil.", en: "The Ta'alam icon now appears as an app on your home screen.", nl: "Het Ta'alam-icoon verschijnt nu als een app op je startscherm.", ar: "أيقونة تعلّم تظهر الآن كتطبيق على شاشتك الرئيسية.", tr: "Ta'alam simgesi artık ana ekranında bir uygulama olarak görünüyor.", ur: "تعلّم کا آئیکن اب آپ کی ہوم اسکرین پر ایک ایپ کے طور پر نظر آتا ہے۔" },
  "install.desktopTitle": { fr: "Sur ordinateur (Chrome ou Edge)", en: "On desktop (Chrome or Edge)", nl: "Op desktop (Chrome of Edge)", ar: "على الحاسوب (كروم أو إيدج)", tr: "Bilgisayarda (Chrome veya Edge)", ur: "ڈیسک ٹاپ پر (کروم یا ایج)" },
  "install.desktopStep1": { fr: "Ouvre Google Chrome ou Microsoft Edge sur ton ordinateur.", en: "Open Google Chrome or Microsoft Edge on your computer.", nl: "Open Google Chrome of Microsoft Edge op je computer.", ar: "افتح جوجل كروم أو مايكروسوفت إيدج على حاسوبك.", tr: "Bilgisayarında Google Chrome veya Microsoft Edge'i aç.", ur: "اپنے کمپیوٹر پر گوگل کروم یا مائیکروسافٹ ایج کھولیں۔" },
  "install.desktopStep2": { fr: "Va sur https://taalam.eu/.", en: "Go to https://taalam.eu/.", nl: "Ga naar https://taalam.eu/.", ar: "اذهب إلى https://taalam.eu/.", tr: "https://taalam.eu/ adresine git.", ur: "https://taalam.eu/ پر جائیں۔" },
  "install.desktopStep3": { fr: "Regarde dans la barre d'adresse : un bouton « Installer l'application » ou une icône d'installation peut apparaître.", en: "Look in the address bar: an 'Install app' button or install icon may appear.", nl: "Kijk in de adresbalk: een 'App installeren' knop of installatie-icoon kan verschijnen.", ar: "انظر في شريط العنوان: قد يظهر زر «تثبيت التطبيق» أو أيقونة التثبيت.", tr: "Adres çubuğuna bak: 'Uygulamayı yükle' düğmesi veya yükleme simgesi görünebilir.", ur: "ایڈریس بار میں دیکھیں: 'ایپ انسٹال کریں' بٹن یا انسٹال آئیکن ظاہر ہو سکتا ہے۔" },
  "install.desktopStep4": { fr: "Clique sur ce bouton puis sur « Installer ».", en: "Click this button then 'Install'.", nl: "Klik op deze knop en dan op 'Installeren'.", ar: "اضغط على هذا الزر ثم على «تثبيت».", tr: "Bu düğmeye, ardından 'Yükle' düğmesine tıkla.", ur: "اس بٹن پر کلک کریں پھر 'انسٹال کریں' پر۔" },
  "install.desktopStep5": { fr: "Ta'alam apparaîtra comme une application dans ton menu Démarrer ou Launchpad.", en: "Ta'alam will appear as an app in your Start menu or Launchpad.", nl: "Ta'alam verschijnt als een app in je Startmenu of Launchpad.", ar: "سيظهر تعلّم كتطبيق في قائمة ابدأ أو Launchpad.", tr: "Ta'alam, Başlat menüsünde veya Launchpad'de bir uygulama olarak görünecek.", ur: "تعلّم آپ کے اسٹارٹ مینو یا لانچ پیڈ میں ایک ایپ کے طور پر ظاہر ہوگا۔" },
  "more.installApp": { fr: "Installer l'app", en: "Install the app", nl: "App installeren", ar: "تثبيت التطبيق", tr: "Uygulamayı yükle", ur: "ایپ انسٹال کریں" },
  "more.installAppDesc": { fr: "Guide pour ajouter Ta'alam à l'écran d'accueil.", en: "Guide to add Ta'alam to your home screen.", nl: "Handleiding om Ta'alam aan je startscherm toe te voegen.", ar: "دليل لإضافة تعلّم إلى شاشتك الرئيسية.", tr: "Ta'alam'ı ana ekranına ekleme rehberi.", ur: "تعلّم کو ہوم اسکرین میں شامل کرنے کا گائیڈ۔" },

